function dt_hood_slug($h){return 'aluguel-de-brinquedos-'.$GLOBALS['dt_hood_data'][$h]['slug'].'-zona-norte';}
function dt_hood_url($h){return home_url('/'.dt_hood_slug($h).'/');}
function dt_hood_by_page_slug($s){foreach($GLOBALS['dt_hood_data'] as $h=>$d) if(dt_hood_slug($h)===$s) return $h; return null;}
function dt_hoods_li($cls=''){
  $o=''; foreach(dt_hoods() as $h) $o.='<li><a href="'.esc_url(dt_hood_url($h)).'">'.esc_html($h).'</a></li>'; return $o;
}
